export function Layout() {
  const [collapsed, setCollapsed] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const { token } = theme.useToken();

  const selectedKey = location.pathname;
  const openKeys = selectedKey.startsWith('/settings') ? ['settings'] : [];

  return (
    <AntLayout style={{ minHeight: '100vh' }}>
      <Sider
        trigger={null}
        collapsible
        collapsed={collapsed}
        theme="light"
        style={{ borderLeft: `1px solid ${token.colorBorderSecondary}` }}
        width={240}
      >
        <div style={{
          height: 60,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontWeight: 700,
          fontSize: collapsed ? 16 : 20,
          color: token.colorPrimary,
          borderBottom: `1px solid ${token.colorBorderSecondary}`,
        }}>
          {collapsed ? 'B' : 'BordUp'}
        </div>
        <Menu
          mode="inline"
          selectedKeys={[selectedKey]}
          defaultOpenKeys={openKeys}
          items={menuItems}
          onClick={({ key }) => navigate(key)}
          style={{ borderInlineStart: 'none' }}
        />
      </Sider>
      <AntLayout>
        <Header style={{
          background: token.colorBgContainer,
          padding: '0 16px',
          display: 'flex',
          alignItems: 'center',
          borderBottom: `1px solid ${token.colorBorderSecondary}`,
        }}>
          <span
            onClick={() => setCollapsed(!collapsed)}
            style={{ fontSize: 18, cursor: 'pointer', marginLeft: 16 }}
          >
            {collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
          </span>
          <span style={{ fontSize: 16, fontWeight: 600 }}>
            {menuItems.find(m => m.key === selectedKey)?.label ||
             menuItems.flatMap(m => (m as any).children || []).find((c: any) => c.key === selectedKey)?.label ||
             'BordUp'}
          </span>
        </Header>
        <Content style={{ margin: 0, padding: 24, overflow: 'auto' }}>
          <Outlet />
        </Content>
      </AntLayout>
    </AntLayout>
  );
}

import mongoose from 'mongoose';

const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017/bordup';

let bucket: mongoose.mongo.GridFSBucket;

export async function connectDatabase(): Promise<void> {
  try {
    const conn = await mongoose.connect(MONGODB_URI);
    console.log('✅ MongoDB متصل:', MONGODB_URI);

    const db = conn.connection.db;
    bucket = new mongoose.mongo.GridFSBucket(db, {
      bucketName: 'files',
    });
  } catch (error) {
    console.error('❌ خطأ في الاتصال بـ MongoDB:', error);
    process.exit(1);
  }
}

export function getBucket(): mongoose.mongo.GridFSBucket {
  if (!bucket) {
    throw new Error('GridFS bucket غير مهيأ. تأكد من الاتصال بقاعدة البيانات أولاً.');
  }
  return bucket;
}

import express from 'express';
import cors from 'cors';
import { connectDatabase } from './config/database';
import { errorHandler, notFoundHandler } from './middleware/error';
import routes from './routes';

const app = express();
const PORT = process.env.PORT || 3001;

// Middleware
app.use(cors());
app.use(express.json({ limit: '100mb' }));
app.use(express.urlencoded({ extended: true, limit: '100mb' }));

// Routes
app.use('/api', routes);

// Error handling
app.use(notFoundHandler);
app.use(errorHandler);

// Start server
async function start(): Promise<void> {
  await connectDatabase();
  app.listen(PORT, () => {
    console.log(`🚀 خادم BordUp يعمل على http://localhost:${PORT}`);
  });
}

