      </AntLayout>
    </AntLayout>
  );
}

import mongoose from 'mongoose';

const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017/bordup';

let bucket: mongoose.mongo.GridFSBucket;

export async function connectDatabase(): Promise<void> {
  try {
    const conn = await mongoose.connect(MONGODB_URI);
    console.log('✅ MongoDB متصل:', MONGODB_URI);

    const db = conn.connection.db;
    bucket = new mongoose.mongo.GridFSBucket(db, {
      bucketName: 'files',
    });
  } catch (error) {
    console.error('❌ خطأ في الاتصال بـ MongoDB:', error);
    process.exit(1);
  }
}

export function getBucket(): mongoose.mongo.GridFSBucket {
  if (!bucket) {
    throw new Error('GridFS bucket غير مهيأ. تأكد من الاتصال بقاعدة البيانات أولاً.');
  }
  return bucket;
}

import express from 'express';
import cors from 'cors';
import { connectDatabase } from './config/database';
import { errorHandler, notFoundHandler } from './middleware/error';
import routes from './routes';

const app = express();
const PORT = process.env.PORT || 3001;

// Middleware
app.use(cors());
app.use(express.json({ limit: '100mb' }));
app.use(express.urlencoded({ extended: true, limit: '100mb' }));

// Routes
app.use('/api', routes);

// Error handling
app.use(notFoundHandler);
app.use(errorHandler);

// Start server
async function start(): Promise<void> {
  await connectDatabase();
  app.listen(PORT, () => {
    console.log(`🚀 خادم BordUp يعمل على http://localhost:${PORT}`);
  });
}

